/**
 * Topbar user menu — account/profile navigation + in-menu locale switcher
 * (subsumes user-popover-menu.spec.ts and the locale-switch half of
 * i18n-smoke.spec.ts).
 *
 * The user menu (platform-chrome) exposes Profile / Account settings / Sign out,
 * a theme radiogroup, and the inline LocaleSwitcher (listbox "Available
 * locales"). Locale native names are data-i18n-allow (not translated), so we
 * locate options by native name even after the surrounding chrome re-renders in
 * the newly-selected locale — and ar-AE flips <html dir> to rtl.
 */
import { userMenu, userMenuButton } from "../../support/selectors";
import { localeListbox } from "./_helpers";
import type { PersonaCreds } from "../../support/commands";

describe("shell: account & user menu", () => {
  let email = "";

  beforeEach(() => {
    cy.login("P4").then((creds: PersonaCreds) => {
      email = creds.email;
    });
    // cy.login leaves the browser on about:blank; visit AFTER it, once per test.
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");
  });

  it("exposes Profile, Account settings and Sign out (no Keyboard shortcuts)", () => {
    userMenuButton().click();
    userMenu().should("be.visible");
    userMenu().findByRole("menuitem", { name: /profile/i }).should("be.visible");
    userMenu()
      .findByRole("menuitem", { name: /account settings/i })
      .should("be.visible");
    userMenu().findByRole("menuitem", { name: /sign out/i }).should("be.visible");
    userMenu()
      .findByRole("menuitem", { name: /keyboard shortcuts/i })
      .should("not.exist");
  });

  it("Profile navigates to /profile and shows the signed-in email", () => {
    userMenuButton().click();
    userMenu().findByRole("menuitem", { name: /profile/i }).click();
    cy.location("pathname", { timeout: 20_000 }).should("match", /\/profile$/);
    cy.findByText(email).should("be.visible");
  });

  it("Account settings navigates to /account with the security sections", () => {
    userMenuButton().click();
    userMenu().findByRole("menuitem", { name: /account settings/i }).click();
    cy.location("pathname", { timeout: 20_000 }).should("match", /\/account$/);
    cy.findByRole("heading", { name: /security/i }).should("be.visible");
    cy.findByRole("heading", { name: /preferences/i }).should("be.visible");
    cy.findByRole("heading", { name: /notifications/i }).should("be.visible");

    // Manage password / 2FA opens the Keycloak account console in a new,
    // rel=noopener tab; the 2FA status badge renders one of the known states.
    cy.findByRole("link", { name: /manage password \/ 2fa/i })
      .should("have.attr", "target", "_blank")
      .and("have.attr", "rel")
      .and("match", /noopener/);
    cy.findByText(/enabled|setup required|not set up|unavailable/i).should(
      "be.visible",
    );
  });

  it("switches locale in-menu: ar-AE flips the page to RTL, English restores LTR", () => {
    userMenuButton().click();
    localeListbox().should("be.visible");

    // Native names are locale-invariant, so they resolve in any active locale.
    localeListbox().findByText("العربية").click();
    cy.document().its("documentElement.dir").should("eq", "rtl");

    cy.findByText("English (US)").click();
    cy.document().its("documentElement.dir").should("eq", "ltr");
  });
});


--- frontends/cypress/cypress/e2e/shell/admin-plane-confinement.cy.ts (97 lines) ---
/**
 * Admin-plane confinement (security invariant 8) — subsumes
 * platform-admin-restricted.spec.ts.
 *
 * A caller bearing a Keycloak REALM admin role (P1) is confined to the admin
 * plane: the workspace BFFs (range/dialogue/files) and the ws-gateway proxy reject
 * them with 403, and the shell FE routes them to a forbidden page + hides the
 * workspace nav. An org-membership OWNER who holds NO realm role (P2) is NOT
 * confined — RejectAdminRoles admits them (they administer their own org while
 * keeping workspace access).
 *
 * The confinement 403 carries a specific message ("...cannot access workspace
 * resources/streams"), distinct from a per-vertical permission 403 — so we assert
 * on that message, not merely the status, to avoid a false pass when a workspace
 * BFF 403s P2 for an unrelated permission reason.
 */

const CONFINEMENT_MSG = /cannot access workspace (resources|streams)/i;

// Workspace routes reachable from the shell origin (shell-bff cookie->bearer
// proxies to each workspace BFF, which runs RejectAdminRoles).
const WORKSPACE_ROUTES = [
  "/api/v1/range/exercises/",
  "/api/v1/files/corpora",
  "/api/v1/dialogue/channels/",
  "/api/v1/ws",
] as const;

function requestRoute(path: string) {
  return cy.request({ url: path, failOnStatusCode: false, timeout: 15_000 });
}

describe("shell: admin-plane confinement", () => {
  describe("P1 realm-admin is confined", () => {
    WORKSPACE_ROUTES.forEach((path) => {
      it(`is rejected with a confinement 403 on ${path}`, () => {
        cy.login("P1");
        requestRoute(path).then((res) => {
          expect(res.status, `${path} status`).to.eq(403);
          expect(
            JSON.stringify(res.body),
            `${path} confinement message`,
          ).to.match(CONFINEMENT_MSG);
        });
      });
    });

    it("lands on /admin after login", () => {
      cy.login("P1");
      cy.visit("/admin");
      cy.location("pathname", { timeout: 30_000 }).should("match", /^\/admin/);
    });

    it("visiting a workspace route shows the platform-admin forbidden page", () => {
      cy.login("P1");
      cy.visit("/range");
      cy.findByRole("heading", {
        name: /not available for platform administrators/i,
        timeout: 30_000,
      }).should("be.visible");
      cy.findByRole("link", { name: /go to admin/i }).should("be.visible");
    });

    it("the primary navigation hides workspace destinations", () => {
      cy.login("P1");
      cy.visit("/admin");
      // Structural anchor (hamburger trigger) — testid is fine for a non-string
      // structural element; the nav destinations below are asserted by role/name.
      cy.get("[data-testid=topbar-nav-trigger]", { timeout: 30_000 }).click();
      const nav = () => cy.findByRole("dialog", { name: /primary navigation/i });
      nav().should("be.visible");
      nav().findByRole("link", { name: /^admin$/i }).should("be.visible");
      nav().findAllByRole("link", { name: /^files$/i }).should("not.exist");
      nav().findAllByRole("link", { name: /^range$/i }).should("not.exist");
      nav()
        .findAllByRole("link", { name: /^dialogue$/i })
        .should("not.exist");
    });
  });

  describe("P2 org-owner (no realm role) is admitted", () => {
    WORKSPACE_ROUTES.forEach((path) => {
      it(`is not confinement-rejected on ${path}`, () => {
        cy.login("P2").then((creds) => {
          expect(creds.degraded, "P2 must be a real org owner").to.eq(false);
          requestRoute(path).then((res) => {
            expect(
              JSON.stringify(res.body),
              `${path} must NOT carry the confinement message`,
            ).to.not.match(CONFINEMENT_MSG);
          });
        });
      });
    });
  });
});


--- frontends/cypress/cypress/e2e/shell/launcher-grid.cy.ts (369 lines) ---
/// <reference types="cypress" />
/**
 * Primary-nav launcher grid (#2601) — the multi-column launcher that
 * replaced the single 280px ORGANIZE column (#2593-#2597). Covers what the
 * refactor actually changed: the dialog contract, the filter header, the
 * 2D keyboard cursor, the preview column, and dead-row rendering — plus a
 * grid-shaped re-check of admin-plane confinement (`admin-plane-
 * confinement.cy.ts` already covers the route/403 side; this only adds the
 * NEW claim that the restructured grid renders NOTHING for the admin
 * plane, not merely that individual links are absent).
 *
 * **Persona limitation (do not paper over):** every loginable Cypress
 * persona (`cypress/fixtures/personas.json`) either has no org membership
 * at all (P1) or mints a FRESH org rather than joining the seeded
 * `seed-default-workspace` (P2-P7), so `GET /api/v1/session/workspaces`
 * always resolves to zero workspaces for every persona this lane can log
 * in as. `PrimaryNavMenu`'s `resolveLiveness` (`src/config/navigation.ts`)
 * treats `hasWorkspace === false` as dead for every app that carries an
 * `mfe` — i.e. every workspace vertical (Files, Rooms, Spaces, Studio,
 * Workflows, Range, Queue, Dialogue, Ask, Monitor). Consequently:
 *   - the "MFE absent renders disabled" coverage below is fully
 *     deterministic (Files is guaranteed dead for every org-member
 *     persona in this environment), but
 *   - the "child destination reachable from the preview column" coverage
 *     can only ever exercise a REAL live child if some future persona
 *     gains a real workspace assignment. Today it self-skips with a GAP
 *     log instead of silently asserting against the always-empty branch —
 *     see `rooms/shell-and-nav.cy.ts`'s file header for the same finding
 *     applied to the ORGANIZE row itself.
 *
 * Selector backing keys (platform-chrome), en-US values:
 *   - nav trigger   user_menu_chrome_topbar_open_nav_aria -> "Open navigation menu"
 *   - nav dialog    user_menu_chrome_primary_nav_aria     -> "Primary navigation"
 *   - filter input  nav_launcher_filter_aria              -> "Filter apps and pages"
 *   - no-matches    nav_launcher_no_results               -> "No matching apps"
 *   - dead row name nav_coming_soon_label                 -> "{label} — Coming soon"
 */
import {
  navMenuDialog,
  navMenuTrigger,
  navSectionList,
} from "../../support/selectors";

interface MfeEntry {
  name: string;
}

interface WorkspacesResponse {
  orgs?: Array<{ workspaces?: unknown[] }>;
}

/** Apps that carry BOTH an `mfe` (subject to the `hasWorkspace` liveness
 *  gate) AND registry `children` (`src/config/navigation.ts`) — the only
 *  candidates that could ever populate the preview column with a real
 *  child link. */
const CHILD_BEARING_WORKSPACE_MFES = [
  "rooms",
  "workflow",
  "queue",
  "dialogue",
  "ask",
  "monitor",
] as const;

function readMfeNames(): Cypress.Chainable<string[]> {
  return cy
    .request({ url: "/api/v1/mfes", failOnStatusCode: false })
    .then((res) => {
      const raw = res.body as MfeEntry[] | { data?: MfeEntry[] };
      const entries = Array.isArray(raw) ? raw : (raw.data ?? []);
      return entries.map((m) => m.name);
    });
}

function readHasWorkspace(): Cypress.Chainable<boolean> {
  return cy
    .request({ url: "/api/v1/session/workspaces", failOnStatusCode: false })
    .then((res) => {
      if (res.status !== 200) return false;
      const body = res.body as WorkspacesResponse;
      const total = (body.orgs ?? []).reduce(
        (n, o) => n + (o.workspaces?.length ?? 0),
        0,
      );
      return total > 0;
    });
}

describe("shell: primary nav launcher grid", () => {
  beforeEach(() => {
    cy.login("P4");
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");
  });

  it("opens as a dialog without aria-modal, and focuses the filter input on open", () => {
    navMenuTrigger().click();
    navMenuDialog().should("be.visible").and("not.have.attr", "aria-modal");
    navMenuDialog().findByRole("searchbox").should("be.focused");
  });

  it("filters rows live by typed text and announces a no-matches state for an unmatched query", () => {
    navMenuTrigger().click();
    navMenuDialog().findByRole("searchbox").type("home");
    navSectionList("start").findByRole("link", { name: /^home$/i }).should("be.visible");
    // A group whose apps all filter out is not rendered at all (its <ul>
    // disappears with it) — organize has no app named "home".
    navSectionList("organize").should("not.exist");

    navMenuDialog().findByRole("searchbox").clear().type("zzzzz-no-such-app");
    navMenuDialog()
      .findByRole("status")
      .should("contain.text", "No matching apps");
    // The grid wrapper itself unmounts once nothing survives the filter.
    navMenuDialog().find("[data-column-index]").should("not.exist");
  });

  it("keyboard: ArrowDown from the filter enters the grid on Home; Enter activates the focused row and closes the dialog, returning focus to the trigger", () => {
    navMenuTrigger().click();
    navMenuDialog().findByRole("searchbox").should("be.focused");

    navMenuDialog().findByRole("searchbox").type("{downarrow}");
    navMenuDialog()
      .find("[data-app-id=home]")
      .should("be.focused")
      .and("have.attr", "tabindex", "0");

    cy.focused().type("{enter}");
    navMenuDialog().should("not.exist");
    navMenuTrigger().should("be.focused");
  });

  it("keyboard: ArrowRight moves the cursor into the next column, and roving tabIndex leaves exactly one grid row tabbable", () => {
    navMenuTrigger().click();
    navMenuDialog().findByRole("searchbox").type("{downarrow}");
    navMenuDialog().find("[data-app-id=home]").should("be.focused");

    cy.focused().type("{rightarrow}");
    // Home lives in column 0 ("start"); the next non-empty column is
    // "organize" (column 1) per LAUNCHER_COLUMN_GROUP_SLUGS.
    cy.focused()
      .closest("[data-column-index]")
      .should("have.attr", "data-column-index", "1");

    // Roving-tabindex contract: exactly one grid row explicitly carries
    // tabindex="0" (LauncherAppItem sets it only on the focused row).
    navMenuDialog()
      .find("[data-column-index] a[data-app-id]")
      .filter('[tabindex="0"]')
      .should("have.length", 1);
  });

  it("a workspace vertical with no workspace assignment renders as a disabled, unfocusable, and unreachable row", () => {
    // Deterministic for every org-member persona in this environment: P4
    // never joins a real workspace (see this file's header), so `files`
    // (which carries an `mfe`) always resolves "dead" regardless of the
    // "files" platform flag's own state.
    navMenuTrigger().click();
    navSectionList("organize")
      .findAllByRole("link", { name: /^files$/i })
      .should("not.exist");
    navSectionList("organize")
      .findByRole("group", { name: /files/i })
      .should("have.attr", "aria-disabled", "true")
      .and("have.attr", "tabindex", "-1");
  });

  it("closes on Escape and returns focus to the trigger", () => {
    navMenuTrigger().click();
    navMenuDialog().should("be.visible");
    cy.get("body").type("{esc}");
    navMenuDialog().should("not.exist");
    navMenuTrigger().should("be.focused");
  });

  it("closes on an outside click and returns focus to the trigger", () => {
    navMenuTrigger().click();
    navMenuDialog().should("be.visible");
    // Anywhere far outside the panel's own footprint.
    cy.get("body").click(5, 5);
    navMenuDialog().should("not.exist");
    navMenuTrigger().should("be.focused");
  });

  it("group headings are headings, not focus stops, and are the label their list is bound to", () => {
    navMenuTrigger().click();
    navMenuDialog()
      .findByRole("heading", { name: /organize/i, level: 3 })
      .should("be.visible")
