/**
 * MfeVersionGate — the build-integrity check wrapping MfeLoader OUTSIDE
 * React.lazy (frontends/platform-chrome/src/MfeVersionGate.tsx, wired in
 * frontends/shell-mfe/src/mfe/MfeLoader.tsx). Compares the registry's
 * `entry.gitSha` (GET /api/v1/mfes) against the remote's own served
 * /version.json `gitSha` (Task 4).
 *
 * This spec covers two of the four terminal states via a stubbed registry
 * PLUS a stubbed /version.json — both entry.gitSha and the actual gitSha are
 * fully under test control, so the skew is deterministic regardless of what
 * gitSha this job's pulled files-mfe image actually bakes in:
 *   - enforce:"warn"   → VersionSkewBanner (role="status", aria-live="polite"),
 *     children still mount underneath it (warn never blocks first paint).
 *   - enforce:"strict" → VersionSkewBlockedScreen (role="alert",
 *     aria-live="assertive"), children do NOT mount.
 *
 * NOTE ON NETWORK TOPOLOGY: MfeVersionGate derives the probed URL as
 * `new URL(entry.url).origin + "/version.json"` — the ORIGIN only, discarding
 * entry.url's path. In this job's topology (platform/compose/e2e-proxy.yml)
 * every MFE is reverse-proxied behind ONE origin (http://localhost:5173,
 * path-routed: /files-mfe/*, /dialogue-mfe/* etc.), so this probe can only
 * ever reach whatever /version.json is served at THAT shared origin's root
 * (shell-mfe's own, if any) — never a per-remote one — regardless of which
 * MFE's entry.url is passed in. Stubbing the version.json GET directly (rather
 * than relying on a live per-remote file) is therefore not just convenient
 * here, it is the only way this spec can reach a specific remote's version
 * probe at all under this proxy topology. Flagging this as a real gap in the
 * live wiring, not a Cypress-only artifact — it affects any real
 * multi-origin skew detection running through e2e-proxy.yml the same way.
 *
 * The `unreachable` and `unknown` states are NOT covered here:
 * `unreachable` (network/429/timeout on the version.json probe) is the same
 * RegistryErrorPanel already covered end-to-end by
 * registry-error-recovery.cy.ts (MfeVersionGate hands off to it verbatim);
 * `unknown` (404 / unparsable / either side "dev") is the default un-stubbed
 * behaviour every other shell/dialogue/files spec already exercises
 * implicitly (mount, silent) every time it visits those routes without this
 * spec's overrides, so isolating it here would be a smoke check, not new
 * signal.
 *
 * Selector backing keys (platform-chrome messages/en-US/common.json):
 *   mfe_version_skew_banner_body  -> "This app was updated. Reload to get the latest version."
 *   mfe_version_skew_reload_cta   -> "Reload"
 *   mfe_version_skew_blocked_title -> "Update required"
 *   mfe_version_skew_blocked_body -> "This app must be reloaded to continue."
 * Structural anchor: [data-testid="files-main"]
 * (frontends/files-mfe/src/layout/FilesLayout.tsx).
 */
import { STUB_MFE_VERSION, type MfeRegistryEntry } from "./_helpers";

const FILES_REMOTE_URL = "http://localhost:5173/files-mfe/assets/remoteEntry.js";
const EXPECTED_GIT_SHA = "expected0000aaaa1111bbbb2222cccc3333dddd";
const ACTUAL_GIT_SHA = "actual0000eeee4444ffff5555aaaa6666bbbb7";

function stubRegistry(enforce: "warn" | "strict"): void {
  const entry: MfeRegistryEntry = {
    name: "files",
    url: FILES_REMOTE_URL,
    version: STUB_MFE_VERSION,
    gitSha: EXPECTED_GIT_SHA,
    enforce,
  };
  cy.intercept("GET", "**/api/v1/mfes", { statusCode: 200, body: { data: [entry] } });
}

/** Stubs the version.json probe with a gitSha that deliberately differs from
 *  EXPECTED_GIT_SHA above, and is not the literal "dev" on either side — the
 *  two conditions MfeVersionGate requires for a genuine "skew" verdict
 *  rather than "unknown". */
function stubVersionJsonSkewed(): void {
  cy.intercept("GET", "**/version.json", {
    statusCode: 200,
    body: {
      name: "files-mfe",
      version: STUB_MFE_VERSION,
      gitSha: ACTUAL_GIT_SHA,
      builtAt: "2026-08-24T00:00:00Z",
    },
  });
}

function visitFiles(): void {
  cy.visit("/files", {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

describe("shell: MfeVersionGate version-skew detection", () => {
  beforeEach(() => {
    cy.login("P4");
    stubVersionJsonSkewed();
  });

  it("enforce:\"warn\" renders the skew banner but still mounts the remote underneath it", () => {
    stubRegistry("warn");
    visitFiles();

    cy.findByRole("status", { timeout: 20_000 }).within(() => {
      cy.findByText(
        /this app was updated\. reload to get the latest version\./i,
      ).should("be.visible");
      cy.findByRole("button", { name: /reload/i }).should("be.visible");
    });

    // warn never blocks first paint — the remote mounts alongside the
    // banner, not instead of it.
    cy.get('[data-testid="files-main"]', { timeout: 20_000 }).should("exist");
  });

  it("enforce:\"strict\" blocks the mount with the update-required screen instead of the remote", () => {
    stubRegistry("strict");
    visitFiles();

    cy.findByRole("alert", { timeout: 20_000 }).within(() => {
      cy.findByText(/update required/i).should("be.visible");
      cy.findByText(/this app must be reloaded to continue\./i).should(
        "be.visible",
      );
      cy.findByRole("button", { name: /reload/i }).should("be.visible");
    });

    // strict holds the remote's mount entirely — its module-init side
    // effects must never have run.
    cy.get('[data-testid="files-main"]').should("not.exist");
  });
});


