/**
 * Shell MFE manifest — admin-plane confinement (security invariant 8).
 *
 * GET /api/v1/mfes returns the set of micro-frontends the caller may mount. The
 * confinement rule:
 *   - P1 realm-admin  -> ONLY the admin MFE (confinement returns immediately).
 *   - P2/P3 org owner/admin (NO realm role) -> admin MFE + the workspace set.
 *   - P4 plain member -> the workspace set, NO admin MFE.
 *
 * `files` always leads the workspace set; the other verticals may be
 * feature-flag-omitted OR simply not wired into the running stack's MFE registry
 * (e.g. workflow's remote URL unset locally), so this spec anchors the workspace
 * set on `files` and never hard-asserts the optional verticals.
 */
import { readMfeEntries, readMfeNames } from "./_helpers";

const ALWAYS_WORKSPACE = ["files"] as const;

describe("shell: /api/v1/mfes admin-plane confinement", () => {
  // The only real guard against Go/TS registry-shape drift: MFEEntry
  // (frontends/platform-chrome/src/useMfeRegistry.ts) is hand-duplicated
  // against shell-bff's Go struct with NO Pact contract and NO proto behind
  // it. The other ~13 specs that hit GET /api/v1/mfes only ever extract
  // `.name` off each entry (readMfeNames), so an additive/renamed/mistyped
  // field elsewhere would sail through every one of them silently — this is
  // the one place the full 5-field wire shape (Task 3) is actually checked.
  it("every entry carries the full 5-field registry shape (name/url/version/gitSha/enforce)", () => {
    cy.login("P4");
    readMfeEntries().then((entries) => {
      expect(entries, "P4 must see at least one MFE").to.have.length.greaterThan(0);
      entries.forEach((entry) => {
        expect(Object.keys(entry).sort(), `entry ${entry.name} keys`).to.deep.eq(
          ["enforce", "gitSha", "name", "url", "version"],
        );
        expect(entry.name, "name").to.be.a("string").and.not.be.empty;
        expect(entry.url, "url").to.be.a("string").and.match(/^https?:\/\//);
        expect(entry.version, "version").to.be.a("string").and.not.be.empty;
        expect(entry.gitSha, "gitSha").to.be.a("string").and.not.be.empty;
        expect(["warn", "strict"], `${entry.name} enforce`).to.include(entry.enforce);
        // The forced invariant: an unpinned build (gitSha "dev", e.g. a
        // hot-federated local MFE) can never be "strict" — that would block
        // every local dev on a version check with no real version to check.
        if (entry.gitSha === "dev") {
          expect(entry.enforce, `${entry.name} enforce when gitSha is "dev"`).to.eq(
            "warn",
          );
        }
      });
    });
  });

  it("P1 realm-admin receives ONLY the admin MFE", () => {
    cy.login("P1");
    readMfeNames().then((names) => {
      expect(names, "P1 mfe names").to.deep.eq(["admin"]);
    });
  });

  it("P2 org-owner receives the admin MFE plus the workspace set", () => {
    cy.login("P2").then((creds) => {
      expect(creds.degraded, "P2 must be a real org owner").to.eq(false);
      readMfeNames().then((names) => {
        expect(names, "P2 includes admin").to.include("admin");
        ALWAYS_WORKSPACE.forEach((w) =>
          expect(names, `P2 includes ${w}`).to.include(w),
        );
      });
    });
  });

  it("P3 org-admin receives the admin MFE plus the workspace set", () => {
    cy.login("P3").then((creds) => {
      expect(creds.degraded, "P3 must be a real org admin").to.eq(false);
      readMfeNames().then((names) => {
        expect(names, "P3 includes admin").to.include("admin");
        ALWAYS_WORKSPACE.forEach((w) =>
          expect(names, `P3 includes ${w}`).to.include(w),
        );
      });
    });
  });

  it("P4 plain member receives the workspace set but NOT the admin MFE", () => {
    cy.login("P4").then((creds) => {
      expect(creds.degraded, "P4 must be a real org member").to.eq(false);
      readMfeNames().then((names) => {
        expect(names, "P4 excludes admin").to.not.include("admin");
        ALWAYS_WORKSPACE.forEach((w) =>
          expect(names, `P4 includes ${w}`).to.include(w),
        );
      });
    });
  });
});


