/**
 * Notifications — REST contract, bell UI, and mark-all-read.
 * Subsumes notifications_mark_read / notifications_ws / notifications_cross_tenant
 * / notifications_invite_accepted.
 *
 * The verifiable-from-this-lane surface (API page shape, bell/panel UI, caught-up
 * empty state, mark-all-read endpoint) is covered live below.
 *
 * The invite-accepted journey has no live drivable path: the notification's
 * recipient is the INVITER, the only inviter the shell admin-proxy accepts is P1
 * (the seed realm admin, which is not a normal recipient), and a real recipient
 * (P2) cannot invite through the proxy. So the recipient's feed is populated via
 * the steward `seedNotification`/`clearNotifications` cy.task (tasks/db.ts —
 * direct Postgres insert keyed on kcUserId + orgId, bypassing RLS as superuser),
 * and the spec then asserts the real UI: unread bell, the "Invite accepted" title,
 * mark-all-read, and cross-tenant isolation.
 */
import { readNotifications } from "./_helpers";
import {
  markAllReadButton,
  notificationsButton,
  notificationsPanel,
} from "./_helpers";

describe("shell: notifications", () => {
  it("P4 GET /api/v1/notifications returns the documented page shape", () => {
    cy.login("P4");
    readNotifications().then((page) => {
      expect(page.notifications, "notifications is an array").to.be.an("array");
      expect(page.unread_count, "unread_count is a number").to.be.a("number");
      expect(page.unread_count).to.be.gte(0);
    });
    cy.request({
      url: "/api/v1/notifications/unread_count",
      failOnStatusCode: false,
    }).then((res) => {
      expect(res.status, "unread_count status").to.eq(200);
    });
  });

  it("P4 opens the notifications bell and reads its panel", () => {
    cy.login("P4");
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");

    notificationsButton().click();
    notificationsPanel().should("be.visible");
    markAllReadButton().should("be.visible");

    // A plain fresh member typically has no notifications -> caught-up empty
    // state; only assert it when the feed is genuinely empty.
    readNotifications().then((page) => {
      if (page.notifications.length === 0) {
        cy.findByText(/you're all caught up/i).should("be.visible");
      }
    });
  });

  it("P4 mark-all-read clears the unread count", () => {
    cy.login("P4");
    cy.request({
      method: "PATCH",
      url: "/api/v1/notifications/read_all",
      failOnStatusCode: false,
    })
      .its("status")
      .should("be.oneOf", [200, 204]);
    readNotifications().then((page) => {
      expect(page.unread_count, "unread_count after mark-all-read").to.eq(0);
    });
  });

  it("invite-accepted: the recipient is notified, marks it read, and other orgs cannot see it", () => {
    const inviteeEmail = `newmember-${Date.now()}@e2e.local`;

    // Seed an invite-accepted notification directly for P2 (the recipient),
    // keyed on kcUserId (== the feed's x-user-id) + orgId (RLS tenant key). This
    // is the steward seam that replaces the live invite->activate->NATS chain,
    // which has no drivable path (the recipient is the inviter, and only a
    // realm admin can invite through the proxy).
    cy.login("P2").then((c) => {
      expect(c.degraded, "P2 must be a real org owner").to.eq(false);
      cy.task("clearNotifications", { recipientUserId: c.kcUserId });
      cy.task("seedNotification", {
        orgId: c.orgId,
        recipientUserId: c.kcUserId,
        inviteeEmail,
      });

      cy.visit("/");
      cy.location("pathname", { timeout: 30_000 }).should("eq", "/");

      // The unread-count fetch is separate from the list hydrate, so assert the
      // bell's unread state first...
      cy.findByRole("button", { name: /unread/i, timeout: 30_000 }).should(
        "be.visible",
      );

      // ...then open the panel and anchor on the stable TITLE. Each row is a
      // button whose accessible name is "Open: {title}", so match by role — that
      // name is computed across the row and is robust to the title being split
      // into child spans (findByText is not).
      notificationsButton().click();
      notificationsPanel().should("be.visible");
      notificationsPanel()
        .findByRole("button", { name: /invite accepted/i, timeout: 15_000 })
        .should("be.visible");

      // Mark everything read -> the bell drops its unread state.
      markAllReadButton().click();
      cy.findAllByRole("button", { name: /unread/i }).should("not.exist");
    });

    // Cross-tenant isolation (RLS): P8, owner of a different org, never sees the
    // notification seeded into P2's org.
    cy.login("P8").then((p8) => {
      expect(p8.degraded, "P8 must be a real org owner").to.eq(false);
      readNotifications().then((feed) => {
        const leaked = feed.notifications.some((n) =>
          `${n.title} ${n.snippet}`
            .toLowerCase()
            .includes(inviteeEmail.toLowerCase()),
        );
        expect(leaked, "org B must not see org A's notification").to.eq(false);
      });
    });
  });
});


