// re-runs mint a distinct child rather than colliding on the slug.
const CHILD_SLUG = `e2e-ws-child-${Date.now()}`;

function readWorkspaces(): Cypress.Chainable<WorkspacesResponse> {
  return cy
    .request({ url: "/api/v1/session/workspaces", failOnStatusCode: false })
    .then((res) => {
      expect(res.status, "GET /api/v1/session/workspaces status").to.eq(200);
      const body = res.body as { data?: WorkspacesResponse } & WorkspacesResponse;
      return (body.data ?? body) as WorkspacesResponse;
    });
