/**
 * Lane-local helpers + selectors for the T1 shell/auth Cypress specs.
 *
 * The shared support/ files (commands, selectors, personas) are steward-owned and
 * frozen; anything the shell lane needs that isn't there lives here. Kept to
 * semantic role/label/text selectors (i18n rule — never a testid for a translated
 * string) plus a couple of small API/session helpers.
 *
 * Selector backing keys (platform-chrome), en-US values, so the case-insensitive
 * regexes below stay locale-portable:
 *   - nav trigger        user_menu_chrome_topbar_open_nav_aria         -> "Open navigation menu"
 *   - nav panel          user_menu_chrome_primary_nav_aria             -> "Primary navigation"
 *   - user-menu trigger  user_menu_chrome_topbar_user_menu_aria        -> "User menu"
 *   - user-menu panel    user_menu_chrome_user_menu_popover_aria       -> "User menu"
 *   - profile item       user_menu_profile                   -> "Profile"
 *   - account item       user_menu_account_settings          -> "Account settings"
 *   - sign out           user_menu_sign_out                  -> "Sign out"
 *   - locale listbox     user_menu_chrome_locale_switcher_available_aria -> "Available locales"
 *   - workspace trigger  user_menu_chrome_topbar_switch_workspace_aria -> "Switch workspace"
 *   - workspace dialog   user_menu_chrome_workspace_switcher_dialog_aria -> "Switch workspace"
 *   - workspace search   user_menu_chrome_workspace_switcher_search_aria -> "Search workspaces"
 *   - workspace list     user_menu_chrome_workspace_switcher_list_aria -> "Workspaces"
 *   - manage link        user_menu_manage_workspaces_link    -> "Manage workspaces"
 *   - notif bell         common_notifications_aria           -> "Notifications"
 *   - notif panel        common_notifications_aria           -> "Notifications"
 *   - mark all read      common_mark_all_read                -> "Mark all read"
 *   - caught-up empty    common_all_caught_up                -> "You're all caught up"
 */

type El = Cypress.Chainable<JQuery<HTMLElement>>;

// ── shell chrome selectors ──────────────────────────────────────────────────

export function workspaceSwitcherButton(): El {
  return cy.findByRole("button", { name: /switch workspace/i });
}
export function workspaceSwitcherDialog(): El {
  return cy.findByRole("dialog", { name: /switch workspace/i });
}
export function workspaceSwitcherList(): El {
  return cy.findByRole("listbox", { name: /workspaces/i });
}
export function workspaceSwitcherSearch(): El {
  return cy.findByRole("searchbox", { name: /search workspaces/i });
}

export function notificationsButton(): El {
  // The bell's accessible name is "Notifications" (unread appends a hardcoded
  // ", N unread" suffix) — match the prefix only so it works read/unread.
  return cy.findByRole("button", { name: /notifications/i });
}
export function notificationsPanel(): El {
  return cy.findByRole("dialog", { name: /notifications/i });
}
export function markAllReadButton(): El {
  return cy.findByRole("button", { name: /mark all read/i });
}

export function localeListbox(): El {
  return cy.findByRole("listbox", { name: /available locales/i });
}

/**
 * Click a topbar popover trigger the way a human does — press, hold, release.
 *
 * Cypress's `.click()` fires pointerdown → pointerup → click back-to-back with
 * no gap, which (like jsdom's `user.click()`) is too compressed to reproduce the
 * external-trigger dismiss-then-reopen defect: measured against a build with the
 * `onInteractOutside` guard reverted, every `.click()`-based toggle assertion
 * passed, while the press-and-hold form below failed on all three popovers.
 * Radix needs a macrotask after mount to attach its outside-pointerdown
 * listener, and React needs a frame to unmount the dismissed panel before the
 * trailing `click` reaches the trigger's own handler. A real press is held for
 * ~100 ms, so hold it here too — this fixed wait simulates human input, it does
 * not paper over a race.
 */
export function humanClick(el: () => El): void {
  const opts = {
    eventConstructor: "PointerEvent",
    pointerType: "mouse",
    button: 0,
    isPrimary: true,
  } as const;
  el().trigger("pointerdown", opts);
  cy.wait(150);
  el().trigger("pointerup", opts).trigger("click", opts);
}

// ── API / session helpers ───────────────────────────────────────────────────

export interface SessionShape {
  user_id: string;
  org_id: string;
  org_role: string;
  roles: string[];
  email: string;
  display_name: string;
  capabilities: Record<string, boolean>;
}

/** GET /api/v1/session, unwrapping a `{ data }` envelope if one is present. */
export function readSession(): Cypress.Chainable<SessionShape> {
  return cy
    .request({ url: "/api/v1/session", failOnStatusCode: false })
    .then((res) => {
      expect(res.status, "GET /api/v1/session status").to.eq(200);
      const body = res.body as { data?: SessionShape } & SessionShape;
      return (body.data ?? body) as SessionShape;
    });
}

/**
 * GET /api/v1/mfes response entry shape — 5 fields (Task 3). `gitSha` is the
 * literal string "dev" when the server has none pinned; `enforce` is forced
 * to "warn" server-side whenever `gitSha === "dev"`. This shape is pinned by
 * NO Pact contract and NO proto (shell-bff is not a Pact provider at all) —
 * `MFEEntry` (frontends/platform-chrome/src/useMfeRegistry.ts) is hand-
 * duplicated against the Go struct that serializes this response, so
 * mfes-manifest.cy.ts's shape assertion is the only real guard against that
 * drift. Enveloped as `{ data: [...] }` (never a bare array) — every helper
 * below still tolerates a bare array defensively, but the live server only
 * ever sends the envelope.
 */
export interface MfeRegistryEntry {
  name: string;
  url: string;
  version: string;
  gitSha: string;
  enforce: "warn" | "strict";
}

/** GET /api/v1/mfes — the raw 5-field entries, unwrapping a `{ data }`
 *  envelope if one is present. Used by mfes-manifest.cy.ts's shape
 *  assertion; most callers only need the names (see readMfeNames below). */
export function readMfeEntries(): Cypress.Chainable<MfeRegistryEntry[]> {
  return cy
    .request({ url: "/api/v1/mfes", failOnStatusCode: false })
    .then((res) => {
      expect(res.status, "GET /api/v1/mfes status").to.eq(200);
      const raw = res.body as
        | MfeRegistryEntry[]
        | { data?: MfeRegistryEntry[] };
      return Array.isArray(raw) ? raw : (raw.data ?? []);
    });
}

/** GET /api/v1/mfes — just the advertised names. Most specs only care which
 *  verticals are present, not the full 5-field entry shape. */
export function readMfeNames(): Cypress.Chainable<string[]> {
  return readMfeEntries().then((entries) => entries.map((m) => m.name));
}

/**
 * Placeholder `version` value for registry-entry STUBS (cy.intercept bodies)
 * across specs that don't care about the field's content — only
 * mfes-manifest.cy.ts's shape assertion cares about the real server's wire
 * shape. Not a real semver; centralized here so no spec hardcodes the
 * literal "0.1.0" directly (the i18n-pseudolocale gate used to).
 */
export const STUB_MFE_VERSION = "0.1.0";

export interface NotificationItem {
  id: string;
  title: string;
  snippet: string;
  kind: string;
}
export interface NotificationsPage {
  notifications: NotificationItem[];
  unread_count: number;
}

/** GET /api/v1/notifications — enveloped `{ data: { notifications, unread_count } }`. */
export function readNotifications(): Cypress.Chainable<NotificationsPage> {
  return cy
    .request({ url: "/api/v1/notifications?limit=50", failOnStatusCode: false })
    .then((res) => {
      expect(res.status, "GET /api/v1/notifications status").to.eq(200);
      const body = res.body as { data?: NotificationsPage };
      const page = body.data ?? (res.body as NotificationsPage);
      return {
        notifications: page.notifications ?? [],
        unread_count: page.unread_count ?? 0,
      };
    });
}

function keycloakOrigin(): string {
  return (Cypress.env("KEYCLOAK_URL") as string) ?? "http://localhost:8080";
}

/**
 * Drive a freshly-INVITED user (already exists in Keycloak with a temp password
 * + UPDATE_PASSWORD required action) through first-login + force-change-password,
 * landing on the shell. This is the invitee's side of the invite→activate flow
 * and is what fires identity.user.activated -> the inviter's notification.
 *
 * Inline cy.origin raw-CSS on Keycloak's own (untranslated) login/update-password
 * pages is the sanctioned exception to the semantic-selector rule.
 */
export function activateInvitedUser(
  email: string,
  tempPassword: string,
  newPassword: string,
): void {
  cy.clearCookies();
  cy.visit("/");
  cy.location("pathname", { timeout: 20_000 }).should("match", /\/login(\/|$)/);
  cy.findByRole("button", { name: /sign in/i }).click();
  cy.origin(
    keycloakOrigin(),
    { args: { email, tempPassword, newPassword } },
    ({ email, tempPassword, newPassword }) => {
      cy.get("input[name=username]", { timeout: 20_000 }).clear().type(email);
      cy.get("input[name=password]").clear().type(tempPassword, { log: false });
      cy.get("input[type=submit], button[type=submit]").click();
      // Keycloak's force-change-password form.
      cy.get("input[name=password-new]", { timeout: 20_000 })
        .clear()
        .type(newPassword, { log: false });
      cy.get("input[name=password-confirm]").clear().type(newPassword, {
        log: false,
      });
      cy.get("input[type=submit], button[type=submit]").click();
    },
  );
  cy.location("host", { timeout: 30_000 }).should("eq", "localhost:5173");
}


