/// <reference types="cypress" />
/**
 * Primary-nav launcher grid (#2601) — the multi-column launcher that
 * replaced the single 280px ORGANIZE column (#2593-#2597). Covers what the
 * refactor actually changed: the dialog contract, the filter header, the
 * 2D keyboard cursor, the preview column, and dead-row rendering — plus a
 * grid-shaped re-check of admin-plane confinement (`admin-plane-
 * confinement.cy.ts` already covers the route/403 side; this only adds the
 * NEW claim that the restructured grid renders NOTHING for the admin
 * plane, not merely that individual links are absent).
 *
 * **Persona limitation (do not paper over):** every loginable Cypress
 * persona (`cypress/fixtures/personas.json`) either has no org membership
 * at all (P1) or mints a FRESH org rather than joining the seeded
 * `seed-default-workspace` (P2-P7), so `GET /api/v1/session/workspaces`
 * always resolves to zero workspaces for every persona this lane can log
 * in as. `PrimaryNavMenu`'s `resolveLiveness` (`src/config/navigation.ts`)
 * treats `hasWorkspace === false` as dead for every app that carries an
 * `mfe` — i.e. every workspace vertical (Files, Rooms, Spaces, Studio,
 * Workflows, Range, Queue, Dialogue, Ask, Monitor). Consequently:
 *   - the "MFE absent renders disabled" coverage below is fully
 *     deterministic (Files is guaranteed dead for every org-member
 *     persona in this environment), but
 *   - the "child destination reachable from the preview column" coverage
 *     can only ever exercise a REAL live child if some future persona
 *     gains a real workspace assignment. Today it self-skips with a GAP
 *     log instead of silently asserting against the always-empty branch —
 *     see `rooms/shell-and-nav.cy.ts`'s file header for the same finding
 *     applied to the ORGANIZE row itself.
 *
 * Selector backing keys (platform-chrome), en-US values:
 *   - nav trigger   user_menu_chrome_topbar_open_nav_aria -> "Open navigation menu"
 *   - nav dialog    user_menu_chrome_primary_nav_aria     -> "Primary navigation"
 *   - filter input  nav_launcher_filter_aria              -> "Filter apps and pages"
 *   - no-matches    nav_launcher_no_results               -> "No matching apps"
 *   - dead row name nav_coming_soon_label                 -> "{label} — Coming soon"
 */
import {
  navMenuDialog,
  navMenuTrigger,
  navSectionList,
} from "../../support/selectors";

interface MfeEntry {
  name: string;
}

interface WorkspacesResponse {
  orgs?: Array<{ workspaces?: unknown[] }>;
}

/** Apps that carry BOTH an `mfe` (subject to the `hasWorkspace` liveness
 *  gate) AND registry `children` (`src/config/navigation.ts`) — the only
 *  candidates that could ever populate the preview column with a real
 *  child link. */
const CHILD_BEARING_WORKSPACE_MFES = [
  "rooms",
  "workflow",
  "queue",
  "dialogue",
  "ask",
  "monitor",
] as const;

function readMfeNames(): Cypress.Chainable<string[]> {
  return cy
    .request({ url: "/api/v1/mfes", failOnStatusCode: false })
    .then((res) => {
      const raw = res.body as MfeEntry[] | { data?: MfeEntry[] };
      const entries = Array.isArray(raw) ? raw : (raw.data ?? []);
      return entries.map((m) => m.name);
    });
}

function readHasWorkspace(): Cypress.Chainable<boolean> {
  return cy
    .request({ url: "/api/v1/session/workspaces", failOnStatusCode: false })
    .then((res) => {
      if (res.status !== 200) return false;
      const body = res.body as WorkspacesResponse;
      const total = (body.orgs ?? []).reduce(
        (n, o) => n + (o.workspaces?.length ?? 0),
        0,
      );
      return total > 0;
    });
