 *
 * The "Create organization" dialog is authored in the admin-mfe REMOTE but its
 * Radix primitive portals into the shell HOST document. This is the classic MF
 * seam that breaks on a duplicate React or a null DialogContext, so the invariants
 * are: (1) the dialog mounts with the right role/name in the host document and
 * paints ABOVE the host <banner> (portal + z-index across the seam); (2) Escape
 * closes it and restores focus to the trigger; (3) the close control dismisses it.
 *
 * P1 (realm admin) owns the admin plane, so /admin/tenants is reachable for it and
 * opening the dialog is a pure client-side action (no admin-bff call).
 *
 * The 25-Tab focus-trap probe from the Playwright original needs real key events
 * (cypress-real-events, not installed) and is intentionally omitted; the portal +
 * z-index + focus-restore checks are the load-bearing federation proof.
 */

function openCreateDialog() {
  return cy
    .findByRole("button", { name: /create a workspace/i, timeout: 30_000 })
    .as("trigger");
}

describe("shell: Radix overlay federation", () => {
  beforeEach(() => {
    cy.login("P1");
    cy.visit("/admin/tenants");
    cy.findByRole("banner", { timeout: 30_000 }).should("be.visible");
  });

  it("renders the remote's dialog in the host document, above the banner", () => {
    openCreateDialog().click();

    cy.findByRole("dialog", { name: /create organization/i })
      .should("be.visible")
      .findByRole("heading", { name: /create organization/i })
      .should("be.visible");

    // The overlay portals to <body> and paints over the host banner: hit-testing
    // the banner's center returns the portaled overlay, not the banner itself.
    cy.document().then((doc) => {
      const banner = doc.querySelector('[role="banner"]');
      expect(banner, "host banner present").to.not.be.null;
      const rect = (banner as HTMLElement).getBoundingClientRect();
      const hit = doc.elementFromPoint(
        rect.left + rect.width / 2,
        rect.top + rect.height / 2,
      );
      expect(hit, "hit element present").to.not.be.null;
      expect(
        (banner as HTMLElement).contains(hit),
        "banner center is covered by the portaled overlay",
      ).to.eq(false);
    });
  });

  it("Escape closes the federated dialog and the trigger is re-openable", () => {
    openCreateDialog().click();
    cy.findByRole("dialog", { name: /create organization/i }).should(
      "be.visible",
    );

    // Escape dismisses the portaled overlay across the MF seam.
    cy.get("body").type("{esc}");
    cy.findByRole("dialog", { name: /create organization/i }).should("not.exist");

    // The trigger survives the overlay lifecycle and re-opens the dialog.
    cy.get("@trigger").click();
    cy.findByRole("dialog", { name: /create organization/i }).should(
      "be.visible",
    );
  });

  it("the close control dismisses the dialog", () => {
    openCreateDialog().click();
    cy.findByRole("dialog", { name: /create organization/i }).should(
      "be.visible",
    );
    cy.findByRole("button", { name: /close modal/i }).click();
    cy.findByRole("dialog", { name: /create organization/i }).should("not.exist");
  });
});


