/**
 * Registry fetch failure recovery — the headline fix behind RegistryErrorPanel
 * and its two consumers (MfeLoader, FeatureAvailabilityGuard).
 *
 * Before this fix, MfeLoader `return null`ed on a failed GET /api/v1/mfes —
 * rendering as a blank page indistinguishable from "still loading" — and
 * FeatureAvailabilityGuard rendered FeatureDisabledPage for BOTH
 * `status === "error"` AND a vertical genuinely absent from a healthy
 * response, so a transient 429 rendered exactly like a platform admin having
 * disabled the vertical (this bug hit all 6 guarded verticals: dialogue,
 * range, studio, spaces, ask, queue, rooms). Both consumers now render
 * RegistryErrorPanel (role="alert", aria-live="assertive", a Retry button)
 * instead; FeatureAvailabilityGuard renders FeatureDisabledPage ONLY once
 * `status === "ready" && !isPresent` — `error` is checked first and returns
 * early.
 *
 * Two routes exercise the two call sites (frontends/shell-mfe/src/App.tsx):
 *   - /files    — MfeLoader only, NO FeatureAvailabilityGuard wrapper —
 *     covers "the panel replaces the blank page" for an UNGUARDED route.
 *   - /dialogue — wrapped in `<FeatureAvailabilityGuard vertical="dialogue">`
 *     — covers "a 429 must never look like a disabled feature" for a
 *     GUARDED route.
 * Both backing MFEs (files-mfe, dialogue-mfe) are up in this job's compose
 * stack (platform/compose/files-mfe.yml, dialogue-mfe.yml — see e2e.yml's
 * COMPOSE_FILES), so a healthy GET /api/v1/mfes would mount them for real; a
 * STICKY cy.intercept override is what forces the error branch
 * deterministically instead (same technique as
 * studio/character-studio-landing.cy.ts's stubAlwaysFails — the app fetches
 * the registry more than once per mount via useMfeRegistryStatus, so a
 * call-counting stub would serve the failure to the first fetch only and the
 * error state would flash and clear before any assertion sees it).
 *
 * Selector backing keys (platform-chrome messages/en-US/common.json),
 * matched case-insensitively:
 *   registry_error_title             -> "Couldn't load the app"
 *   registry_error_body              -> "Something went wrong loading the app. Try again."
 *   registry_error_rate_limited_body -> "Too many requests. Try again in {seconds}s."
 *   mfe_retry                        -> "Retry"
 *   feature_disabled_title           -> "This feature isn't available right now"
 * Structural anchors (real markup, not translated): [data-testid="files-main"]
 * (frontends/files-mfe/src/layout/FilesLayout.tsx) and
 * [data-testid="dialogue-main"] (frontends/dialogue-mfe/src/layout/
 * DialogueLayout.tsx) — asserted absent, proving the MFE never mounted
 * underneath the panel.
 */

/** Force every GET /api/v1/mfes to fail the same way for the life of the
 *  test — see the file header for why a call-counting stub would flake. */
function stubMfesAlwaysFails(
  statusCode: number,
  headers?: Record<string, string>,
): void {
  cy.intercept("GET", "**/api/v1/mfes", {
    statusCode,
    headers,
    body: { error: { message: "stubbed failure" } },
  }).as("mfesFailing");
}

function visit(path: string): void {
  cy.visit(path, {
    onBeforeLoad(win) {
      win.localStorage.setItem("omnicore.locale", "en-US");
    },
  });
}

describe("shell: registry fetch failure renders RegistryErrorPanel, never a blank page or feature-disabled page", () => {
  beforeEach(() => {
    cy.login("P4");
  });

  it("an UNGUARDED route (/files) renders the panel — not a blank page — when GET /api/v1/mfes 500s", () => {
    stubMfesAlwaysFails(500);
    visit("/files");

    cy.findByRole("alert", { timeout: 20_000 }).within(() => {
      cy.findByText(/couldn't load the app/i).should("be.visible");
      cy.findByText(/something went wrong loading the app\. try again\./i).should(
        "be.visible",
      );
      cy.findByRole("button", { name: /retry/i })
        .should("be.visible")
        .and("not.be.disabled");
    });

    // The MFE never mounted underneath — the panel is real content, not a
    // silent `return null` masquerading as "still loading".
    cy.get('[data-testid="files-main"]').should("not.exist");
  });

  it("a 429 on GET /api/v1/mfes renders the panel on a GUARDED vertical (/dialogue) — NEVER the feature-disabled page", () => {
    stubMfesAlwaysFails(429, { "Retry-After": "45" });
    visit("/dialogue");

    cy.findByRole("alert", { timeout: 20_000 }).within(() => {
      cy.findByText(/couldn't load the app/i).should("be.visible");
      // The rate_limited body surfaces the server's Retry-After window —
      // bodyForError branches on error.kind, so this is NOT the generic
      // registry_error_body text.
      cy.findByText(/too many requests\. try again in \d+s\./i).should(
        "be.visible",
      );
      // Retry disabled for the countdown: hammering an org-wide shared 429
      // bucket immediately would just burn another token for nothing.
      cy.findByRole("button", { name: /retry/i }).should("be.disabled");
    });

    // THE headline assertion this task exists to prove: a transient 429
    // must never render as "this feature is disabled". Before the fix,
    // FeatureAvailabilityGuard conflated status==="error" with a genuinely
    // absent vertical and rendered FeatureDisabledPage for both.
    cy.findByRole("heading", { name: /this feature isn't available right now/i }).should(
      "not.exist",
    );
    cy.contains(/this feature isn't available right now/i).should("not.exist");
    cy.get('[data-testid="dialogue-main"]').should("not.exist");
  });
});


