import type { PersonaId } from "../../support/personas";
import type { PersonaCreds } from "../../support/commands";
import { readSession } from "./_helpers";

const CAP_KEYS = [
  "can_change_org_status",
  "can_invite",
  "can_assign_roles",
  "can_remove",
  "can_mutate_workspace_settings",
  "can_mutate_integrations",
  "can_use_api_keys",
] as const;

type CapKey = (typeof CAP_KEYS)[number];
type CapMatrix = Record<CapKey, boolean>;

const OWNER_CAPS: CapMatrix = {
  can_change_org_status: true,
  can_invite: true,
  can_assign_roles: true,
  can_remove: true,
  can_mutate_workspace_settings: true,
  can_mutate_integrations: true,
  can_use_api_keys: true,
};
const ADMIN_CAPS: CapMatrix = { ...OWNER_CAPS, can_change_org_status: false };
const MEMBER_CAPS: CapMatrix = {
  can_change_org_status: false,
  can_invite: false,
  can_assign_roles: false,
  can_remove: false,
  can_mutate_workspace_settings: false,
  can_mutate_integrations: false,
  can_use_api_keys: true,
};
const VIEWER_CAPS: CapMatrix = {
  can_change_org_status: false,
  can_invite: false,
  can_assign_roles: false,
  can_remove: false,
  can_mutate_workspace_settings: false,
  can_mutate_integrations: false,
  can_use_api_keys: false,
};

const CASES: Array<{
  persona: PersonaId;
  role: string;
  caps: CapMatrix;
}> = [
  { persona: "P2", role: "OWNER", caps: OWNER_CAPS },
  { persona: "P3", role: "ADMIN", caps: ADMIN_CAPS },
  { persona: "P4", role: "MEMBER", caps: MEMBER_CAPS },
  { persona: "P5", role: "VIEWER", caps: VIEWER_CAPS },
];

describe("shell: session org_role + capabilities", () => {
  CASES.forEach(({ persona, role, caps }) => {
    it(`${persona} resolves org_role ${role} with the ${role} capability set`, () => {
      cy.login(persona).then((creds: PersonaCreds) => {
        // A degraded (Keycloak-only) mint means admin-bff/org-svc was down and
        // the membership never landed — the role assertions below would be
        // meaningless. Fail loud rather than silently pass on org_role "".
        expect(
          creds.degraded,
          `${persona} must be a real org member (admin-bff/org-svc up)`,
        ).to.eq(false);

        readSession().then((session) => {
          expect(session.org_role, `${persona} org_role`).to.eq(role);
          CAP_KEYS.forEach((key) => {
            expect(
              session.capabilities[key],
              `${persona} capabilities.${key}`,
            ).to.eq(caps[key]);
          });
        });
      });
    });
  });
});


