/**
 * Shell theme tokens — Task 4.6 (stylesheet collapse).
 *
 * frontends/shell-mfe/src/styles/index.css is the ONLY MFE stylesheet that
 * applies under module federation: every other remote imports its own
 * index.css from main.tsx (never the exposed XApp.tsx it actually mounts as),
 * and all 15 stylesheets set cssCodeSplit: false, so a remote's own CSS is
 * effectively invisible once it's federated into shell. Shell's stylesheet is
 * what every user actually gets, in every vertical, always. A defect there
 * is production-wide, not MFE-local.
 *
 * This branch already found two such defects while collapsing shell onto the
 * generated frontends/design-tokens/dist/base.css:
 *   - --cog-warning was entirely absent from shell's :root, so
 *     `bg-cog-warning` / `text-cog-warning` resolved `rgb(var(--cog-warning))`
 *     against an undefined custom property — an invalid color, which computes
 *     to the property's initial value (transparent), not an error.
 *   - `cog-focus-ring` was a phantom class (never defined anywhere), so the
 *     account/profile routes' keyboard focus ring was invisible.
 *
 * Both defects share a shape: an invalid/absent CSS custom property doesn't
 * fail the build — it silently degrades to transparent. A `grep`-the-source
 * check can't catch that; it has to be resolved in a real browser and
 * inspected via computed style, in both themes (light is default; dark
 * activates on `data-theme="dark"` on <html> per the ThemeProvider contract
 * — same mechanism as monitor/search.cy.ts, workflow/brand-profile.cy.ts,
 * range/submissions-aar.cy.ts).
 *
 * NOT EXECUTED — see task notes. Authored and wired into e2e.yml's shell
 * step; run manually against a live stack to get first execution signal.
 */
import { userMenuButton } from "../../support/selectors";

type RGB = readonly [number, number, number];

const LIGHT = {
  canvas: [246, 245, 242] as RGB,
  focus: [39, 66, 201] as RGB,
  warning: [124, 61, 8] as RGB,
};

const DARK = {
  canvas: [12, 14, 18] as RGB,
  focus: [251, 191, 36] as RGB,
  warning: [251, 191, 36] as RGB,
};

function rgbString([r, g, b]: RGB): string {
  return `rgb(${r}, ${g}, ${b})`;
}

/** Reads a `--cog-*` custom property off <html>'s computed style, as "r g b". */
function readCogVar(doc: Document, name: string): string {
  const view = doc.defaultView ?? window;
  return view
    .getComputedStyle(doc.documentElement)
    .getPropertyValue(name)
    .trim();
}

describe("shell: theme tokens resolve under module federation", () => {
  beforeEach(() => {
    cy.login("P4");
    // cy.login leaves the browser on about:blank; visit AFTER it.
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");
  });

  it("light mode: --cog-canvas/--cog-focus/--cog-warning resolve to real RGB triples, not undefined", () => {
    cy.document().then((doc) => {
      expect(readCogVar(doc, "--cog-canvas")).to.eq(LIGHT.canvas.join(" "));
      expect(readCogVar(doc, "--cog-focus")).to.eq(LIGHT.focus.join(" "));
      // The regression this guards: absent from shell's :root meant this
      // read back as "" (empty string), not a triple.
      expect(readCogVar(doc, "--cog-warning")).to.eq(LIGHT.warning.join(" "));
    });
  });

  it("light mode: body paints the resolved canvas color, not transparent", () => {
    cy.get("body").should(($body) => {
      const bg = window.getComputedStyle($body.get(0) as HTMLElement)
        .backgroundColor;
      expect(bg).to.not.eq("rgba(0, 0, 0, 0)");
      expect(bg).to.not.eq("transparent");
      expect(bg).to.eq(rgbString(LIGHT.canvas));
    });
  });

  it("light mode: the topbar user-menu trigger shows a non-transparent focus-visible outline", () => {
    userMenuButton().focus();
    userMenuButton().should(($el) => {
      const outline = window.getComputedStyle($el.get(0) as HTMLElement);
      expect(outline.outlineStyle).to.eq("solid");
      expect(outline.outlineColor).to.not.eq("transparent");
      expect(outline.outlineColor).to.eq(rgbString(LIGHT.focus));
    });
  });

  it("dark mode: the same three tokens flip to their dark values and repaint (not stuck on light or transparent)", () => {
    cy.document().then((doc) => {
      doc.documentElement.setAttribute("data-theme", "dark");
    });
    cy.get("html").should("have.attr", "data-theme", "dark");

    cy.document().then((doc) => {
      expect(readCogVar(doc, "--cog-canvas")).to.eq(DARK.canvas.join(" "));
      expect(readCogVar(doc, "--cog-focus")).to.eq(DARK.focus.join(" "));
      expect(readCogVar(doc, "--cog-warning")).to.eq(DARK.warning.join(" "));
    });

    cy.get("body").should(($body) => {
      const bg = window.getComputedStyle($body.get(0) as HTMLElement)
        .backgroundColor;
      expect(bg).to.not.eq("rgba(0, 0, 0, 0)");
      expect(bg).to.not.eq("transparent");
      expect(bg).to.eq(rgbString(DARK.canvas));
    });

    userMenuButton().focus();
    userMenuButton().should(($el) => {
      const outline = window.getComputedStyle($el.get(0) as HTMLElement);
      expect(outline.outlineStyle).to.eq("solid");
      expect(outline.outlineColor).to.not.eq("transparent");
      expect(outline.outlineColor).to.eq(rgbString(DARK.focus));
    });
  });
});


