/**
 * Topbar popover toggles — every trigger both OPENS and CLOSES its own panel.
 *
 * Each topbar panel is mounted by Topbar and positioned against a trigger
 * button that also lives in Topbar, reached through `Popover.Anchor virtualRef`
 * (nav menu, notifications, user menu) or a zero-size `Popover.Trigger`
 * placeholder (workspace switcher). Radix's own PopoverContent ignores outside
 * interactions that land on its Trigger, leaving the close to that trigger's
 * onClick — but an external trigger is invisible to that guard, so a pointerdown
 * on the real button dismissed the panel and the button's own onClick flipped the
 * (already false) open state back to true. The panel reopened, and the trigger
 * could open a panel but never close it.
 *
 * This lives in Cypress because a real browser is the only place the defect
 * shows: Radix attaches its outside-pointerdown listener a macrotask after
 * mount, and jsdom + `user.click()` compress press → release tightly enough
 * that the dismiss-then-reopen race disappears. The Vitest suite reproduces it
 * only by splitting press and release by hand.
 *
 * The workspace switcher is the fourth such trigger; its toggle assertion lives
 * in workspace-switch.cy.ts, which already provisions the child workspace the
 * trigger needs in order to render at all.
 *
 * Selector backing keys (platform-chrome), en-US values:
 *   - nav trigger        user_menu_chrome_topbar_open_nav_aria    -> "Open navigation menu"
 *   - nav panel          user_menu_chrome_primary_nav_aria        -> "Primary navigation"
 *   - notif bell/panel   common_notifications_aria      -> "Notifications"
 *   - user-menu trigger  user_menu_chrome_topbar_user_menu_aria   -> "User menu"
 *   - user-menu panel    user_menu_chrome_user_menu_popover_aria  -> "User menu"
 */
import {
  navMenuDialog,
  navMenuTrigger,
  userMenuButton,
} from "../../support/selectors";
import { humanClick, notificationsButton } from "./_helpers";

type El = Cypress.Chainable<JQuery<HTMLElement>>;

interface TopbarPopover {
  /** Name used in the test title. */
  readonly what: string;
  readonly trigger: () => El;
  /** Role + accessible name of the panel the trigger owns. */
  readonly panelRole: string;
  readonly panelName: RegExp;
}

const POPOVERS: readonly TopbarPopover[] = [
  {
    what: "nav menu",
    trigger: navMenuTrigger,
    panelRole: "dialog",
    panelName: /primary navigation/i,
  },
  {
    what: "notifications popover",
    trigger: notificationsButton,
    panelRole: "dialog",
    panelName: /notifications/i,
  },
  {
    what: "user menu",
    trigger: userMenuButton,
    panelRole: "menu",
    panelName: /user menu/i,
  },
];

describe("shell: topbar popover toggles", () => {
  beforeEach(() => {
    cy.login("P4");
    // cy.login leaves the browser on about:blank; visit AFTER it.
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");
  });

  POPOVERS.forEach(({ what, trigger, panelRole, panelName }) => {
    it(`${what}: the trigger opens, closes, and reopens the panel`, () => {
      humanClick(trigger);
      cy.findByRole(panelRole, { name: panelName }).should("be.visible");
      trigger().should("have.attr", "aria-expanded", "true");

      // The regression: before the guard this second click left the panel open.
      humanClick(trigger);
      cy.findByRole(panelRole, { name: panelName }).should("not.exist");
      trigger().should("have.attr", "aria-expanded", "false");

      // …and the trigger still opens it again afterwards.
      humanClick(trigger);
      cy.findByRole(panelRole, { name: panelName }).should("be.visible");
      trigger().should("have.attr", "aria-expanded", "true");
    });

    it(`${what}: Escape still dismisses the panel`, () => {
      trigger().click();
      cy.findByRole(panelRole, { name: panelName }).should("be.visible");

      cy.get("body").type("{esc}");

      cy.findByRole(panelRole, { name: panelName }).should("not.exist");
      trigger().should("have.attr", "aria-expanded", "false");
    });
  });

  it("the nav menu no longer offers the removed footer rows", () => {
    navMenuTrigger().click();
    navMenuDialog().within(() => {
      // Removed outright (not "Coming soon" placeholders) — these surfaces are
      // not planned, so their rows and message keys are both gone.
      cy.findByText(/^All Users$/).should("not.exist");
      cy.findByText(/^Manage Organi[sz]ations$/).should("not.exist");
      cy.findByText(/^Course Approvals$/).should("not.exist");
      cy.findByText(/^Observability$/).should("not.exist");
      // What's New was the last row in the footer divider block, so the row
      // and its message key are gone too — and with them the whole block.
      cy.findByText(/What.s New/i).should("not.exist");
    });
  });
});


