/**
 * Workspace switcher UI + tenant context (subsumes workspace-switch.spec.ts and
 * invite_with_workspace_switcher.spec.ts).
 *
 * The topbar workspace switcher only renders when the caller is a member of ≥1
 * CHILD workspace (Topbar counts orgs[].workspaces, not the org root). A freshly
 * minted org owner has just a bare org, so this spec seeds one child workspace
 * under P2's org and adds P2 to it — via the shell admin-proxy as P1 (a realm
 * admin whose token the proxy forwards to admin-bff) — then drives the switcher as
 * P2. It pins: the switcher structure, its wiring to the real server tenant
 * context (active_org_id === /session org_id), and its search filter.
 *
 * NOTE: the cross-ORG switch (pick org B -> reload -> /session org_id changes)
 * needs a persona holding TWO org memberships, which no cy.login persona provides
 * today; that assertion is reported as a gap for a steward two-org persona helper.
 */
import {
  humanClick,
  workspaceSwitcherButton,
  workspaceSwitcherDialog,
  workspaceSwitcherList,
  workspaceSwitcherSearch,
  readSession,
} from "./_helpers";

interface WorkspacesResponse {
  active_org_id: string;
  orgs: Array<{ id: string; name: string }>;
}

// Unique per cypress run so the first before() creates the child cleanly (201);
// re-runs mint a distinct child rather than colliding on the slug.
const CHILD_SLUG = `e2e-ws-child-${Date.now()}`;

function readWorkspaces(): Cypress.Chainable<WorkspacesResponse> {
  return cy
    .request({ url: "/api/v1/session/workspaces", failOnStatusCode: false })
    .then((res) => {
      expect(res.status, "GET /api/v1/session/workspaces status").to.eq(200);
      const body = res.body as { data?: WorkspacesResponse } & WorkspacesResponse;
      return (body.data ?? body) as WorkspacesResponse;
    });
}

describe("shell: workspace switcher", () => {
  before(() => {
    // Resolve P2's org + Keycloak sub, then (as P1) create a child workspace
    // under that org and add P2 to it so P2's switcher has something to list.
    cy.login("P2").then((p2) => {
      expect(p2.degraded, "P2 must be a real org owner").to.eq(false);
      const orgId = p2.orgId as string;
      const sub = p2.kcUserId;

      cy.login("P1");
      cy.request({
        method: "POST",
        url: "/api/v1/admin/tenants",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": crypto.randomUUID(),
        },
        body: { name: "E2E Workspace Child", slug: CHILD_SLUG, parent_id: orgId },
        failOnStatusCode: false,
      }).then((res) => {
        expect(res.status, "child workspace create").to.eq(201);
        const body = res.body as { data?: { tenant?: { id?: string } } };
        const childId = body.data?.tenant?.id as string;
        expect(childId, "child workspace id").to.be.a("string").and.not.be.empty;

        cy.request({
          method: "POST",
          url: `/api/v1/admin/tenants/${childId}/members`,
          headers: {
            "Content-Type": "application/json",
            "Idempotency-Key": crypto.randomUUID(),
          },
          body: { user_id: sub, role: "member" },
          failOnStatusCode: false,
        })
          .its("status")
          .should("be.oneOf", [201, 409]);
      });
    });
  });

  beforeEach(() => {
    cy.login("P2");
    cy.visit("/");
    cy.location("pathname", { timeout: 30_000 }).should("eq", "/");
  });

  it("opens the switcher and lists the workspaces", () => {
    workspaceSwitcherButton().click();
    workspaceSwitcherDialog().should("be.visible");
    workspaceSwitcherSearch().should("be.visible");
    workspaceSwitcherList().should("be.visible");
    workspaceSwitcherList().findAllByRole("option").should("have.length.gte", 1);

    // Owner-only affordance.
    workspaceSwitcherDialog()
      .findByRole("link", { name: /manage workspaces/i })
      .should("be.visible");
  });

  // The trigger is the fourth external-trigger popover in the topbar (see
  // topbar-popover-toggles.cy.ts for the shared defect). It lives here because
  // this spec's before() provisions the child workspace the trigger needs in
  // order to render at all.
  it("closes and reopens the switcher from its own trigger", () => {
    humanClick(workspaceSwitcherButton);
    workspaceSwitcherDialog().should("be.visible");
    workspaceSwitcherButton().should("have.attr", "aria-expanded", "true");

    // The regression: before the onInteractOutside guard, the pointerdown
    // dismissed the panel and the trigger's own click reopened it. humanClick
    // (not .click()) is what surfaces that — see its docs in _helpers.
    humanClick(workspaceSwitcherButton);
    cy.findAllByRole("dialog", { name: /switch workspace/i }).should(
      "have.length",
      0,
    );
    workspaceSwitcherButton().should("have.attr", "aria-expanded", "false");

    humanClick(workspaceSwitcherButton);
    workspaceSwitcherDialog().should("be.visible");
  });

  it("reflects the real server tenant context", () => {
    readSession().then((session) => {
      readWorkspaces().then((ws) => {
        expect(ws.active_org_id, "active_org_id === session org_id").to.eq(
          session.org_id,
        );
        expect(ws.orgs.length, "at least one org").to.be.gte(1);
      });
    });
  });

  it("filters the workspace list by search", () => {
    workspaceSwitcherButton().click();
    workspaceSwitcherList()
      .findAllByRole("option")
      .then(($opts) => {
        const before = $opts.length;
        workspaceSwitcherSearch().type("zzz-no-such-workspace-zzz");
        workspaceSwitcherDialog()
          .findAllByRole("option")
          .should("have.length.lessThan", before);
      });
  });
});



